export const getAnswerQuestionUrl = (id: string,
    questionId: string,) => {




  return `/api/projects/${id}/questions/${questionId}/answer`
}

/**
 * @summary Answer a clarification question
 */
export const answerQuestion = async (id: string,
    questionId: string,
    questionAnswer: QuestionAnswer, options?: RequestInit): Promise<ClarificationQuestion> => {

  return customFetch<ClarificationQuestion>(getAnswerQuestionUrl(id,questionId),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...options?.headers },
    body: JSON.stringify(questionAnswer)
  }
);}





export const getAnswerQuestionMutationOptions = <TError = ErrorType<unknown>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof answerQuestion>>, TError,{id: string;questionId: string;data: BodyType<QuestionAnswer>}, TContext>, request?: SecondParameter<typeof customFetch>}
): UseMutationOptions<Awaited<ReturnType<typeof answerQuestion>>, TError,{id: string;questionId: string;data: BodyType<QuestionAnswer>}, TContext> => {

const mutationKey = ['answerQuestion'];
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof answerQuestion>>, {id: string;questionId: string;data: BodyType<QuestionAnswer>}> = (props) => {
          const {id,questionId,data} = props ?? {};

          return  answerQuestion(id,questionId,data,requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

    export type AnswerQuestionMutationResult = NonNullable<Awaited<ReturnType<typeof answerQuestion>>>
    export type AnswerQuestionMutationBody = BodyType<QuestionAnswer>
    export type AnswerQuestionMutationError = ErrorType<unknown>

    /**
 * @summary Answer a clarification question
 */
export const useAnswerQuestion = <TError = ErrorType<unknown>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof answerQuestion>>, TError,{id: string;questionId: string;data: BodyType<QuestionAnswer>}, TContext>, request?: SecondParameter<typeof customFetch>}
 ): UseMutationResult<
        Awaited<ReturnType<typeof answerQuestion>>,
        TError,
        {id: string;questionId: string;data: BodyType<QuestionAnswer>},
        TContext
      > => {
      return useMutation(getAnswerQuestionMutationOptions(options));
    }

